def verifier(assign):
    import math
    # Extract values
    try:
        a11 = float(assign['a11']); a12 = float(assign['a12']); a22 = float(assign['a22'])
        h = float(assign['h']); k = float(assign['k']); r = float(assign['r'])
        u0 = float(assign['u0']); u1 = float(assign['u1']); u2 = float(assign['u2'])
        v0 = float(assign['v0']); v1 = float(assign['v1']); v2 = float(assign['v2'])
    except Exception:
        # Missing fields
        return (False, None)

    # Basic domain checks
    if not (a11 > 0 and a22 > 0 and a11*a22 - a12*a12 > 1e-6):
        # Not SPD matrix
        return (False, None)
    if not (r > 0):
        return (False, None)

    # Cholesky factor L (lower) for M = [[a11,a12],[a12,a22]] = L L^T
    L11 = math.sqrt(a11)
    L21 = a12 / L11
    rem = a22 - L21*L21
    if rem <= 0:
        return (False, None)
    L22 = math.sqrt(rem)

    # Helper solve L w = v
    def solve_lower(vx, vy):
        y1 = vx / L11
        y2 = (vy - L21*y1) / L22
        return y1, y2

    # Ensure ellipse lies in positive quadrant (x>0,y>0)
    w1 = solve_lower(1.0, 0.0)
    w2 = solve_lower(0.0, 1.0)
    vx_norm = math.hypot(w1[0], w1[1])
    vy_norm = math.hypot(w2[0], w2[1])
    if h - r*vx_norm <= 1e-6 or k - r*vy_norm <= 1e-6:
        # Part of ellipse leaves positive quadrant; we enforce harder constraint
        return (False, None)

    # Transform vectors for the reduced 1D problem
    b1,b2 = solve_lower(u1, u2)
    d1,d2 = solve_lower(v1, v2)
    b1 *= r; b2 *= r
    d1 *= r; d2 *= r
    bnorm = math.hypot(b1, b2)
    dnorm = math.hypot(d1, d2)

    A = u0 + u1*h + u2*k
    C = v0 + v1*h + v2*k

    # Denominator positivity on full circle: C - ||d|| must be positive
    if C <= dnorm + 1e-7:
        return (False, None)
    # Numerator kept positive to avoid sign changes (difficulty condition)
    if A <= bnorm + 1e-7:
        return (False, None)

    # Difficulty: require nontrivial rotation and nonaligned directions
    if abs(a12) < 0.2:
        return (False, None)
    if bnorm < 1e-10 or dnorm < 1e-10:
        return (False, None)
    cos_bd = abs((b1*d1 + b2*d2) / (bnorm*dnorm))
    if cos_bd > 0.97:
        return (False, None)

    def fphi(phi):
        cp = math.cos(phi)
        sp = math.sin(phi)
        num = A + b1*cp + b2*sp
        denlin = C + d1*cp + d2*sp
        if denlin <= 0:
            return float('inf')
        return num / math.sqrt(denlin)

    # Global search with refinement
    N = 4096
    best_phi = 0.0
    best_val = float('inf')
    for i in range(N):
        phi = (2*math.pi)*i/N
        val = fphi(phi)
        if val < best_val:
            best_val = val
            best_phi = phi
    # Golden-section refinement
    w = 6*(2*math.pi)/N
    left = best_phi - w
    right = best_phi + w
    invphi = (math.sqrt(5) - 1)/2
    invphi2 = (3 - math.sqrt(5))/2
    a = left
    b_ = right
    hseg = b_ - a
    cpt = a + invphi2*hseg
    dpt = a + invphi*hseg
    fc = fphi(cpt)
    fd = fphi(dpt)
    for _ in range(100):
        if fc < fd:
            b_ = dpt
            dpt = cpt
            fd = fc
            hseg = b_ - a
            cpt = a + invphi2*hseg
            fc = fphi(cpt)
        else:
            a = cpt
            cpt = dpt
            fc = fd
            hseg = b_ - a
            dpt = a + invphi*hseg
            fd = fphi(dpt)
    phi_min = (a + b_) / 2
    ans = fphi(phi_min)

    if not (ans > 0 and math.isfinite(ans)):
        return (False, None)

    return (True, ans)
